when HTTP_REQUEST {
    if { [active_members pool_web_443] == 0 } {
        HTTP::respond 503 content "<h1>Bakım çalışması</h1>" "Content-Type" "text/html"
    }
}

when HTTP_REQUEST {
    if { [HTTP::cookie exists "SESSID"] } {
        persist uie [HTTP::cookie "SESSID"] 1800
    }
}
when HTTP_RESPONSE {
    if { [HTTP::cookie exists "SESSID"] } {
        persist add uie [HTTP::cookie "SESSID"] 1800
    }
}

when HTTP_REQUEST {
    switch -glob [string tolower [HTTP::host]] {
        "api.example.internal" { pool pool_api_443 }
        "www.example.internal" { pool pool_web_443 }
        default { pool pool_default_80 }
    }
}

when HTTP_REQUEST { set t0 [clock milliseconds] }
when HTTP_RESPONSE {
    set dur [expr {[clock milliseconds] - $t0}]
    if { $dur > 3000 } {
        log local0.warn "SLOW uri=[HTTP::uri] ms=$dur server=[LB::server addr]"
    }
}

when HTTP_REQUEST {
    if { [HTTP::uri] starts_with "/admin" && ![IP::addr [IP::client_addr] equals 198.51.100.0/24] } {
        HTTP::respond 403 content "Forbidden"
    }
}

when HTTP_RESPONSE {
    HTTP::header insert Strict-Transport-Security "max-age=31536000; includeSubDomains"
    HTTP::header insert X-Content-Type-Options "nosniff"
    HTTP::header remove Server
}
